(window.DOM_LAMLA=window.DOM_LAMLA||{})["circulation-1"]={"lecture":"circulation-1","chapters":[{"slug":"cv-introduction","must":[{"star":true,"html":"<strong>Circulatory transport</strong> is necessary because diffusion alone cannot deliver oxygen and nutrients fast enough over large tissue distances."},{"star":false,"html":"<strong>Microvascular proximity</strong> brings blood within micrometres of cells → short diffusion distances allow rapid exchange."},{"star":true,"html":"<strong>Pulmonary circulation</strong> carries right ventricular blood to lungs for oxygenation → pulmonary veins deliver it to left atrium."},{"star":true,"html":"<strong>Systemic circulation</strong> carries left ventricular blood to organs → systemic veins return it to the right atrium."},{"star":false,"html":"<strong>Circulations in series</strong> require equal long-term right and left ventricular output because persistent mismatch would accumulate blood in one circuit."},{"star":false,"html":"<strong>Systemic organ branches</strong> lie in parallel → each tissue receives arterial blood and can control its resistance separately."},{"star":false,"html":"<strong>Coronary arteries</strong> provide a separate arterial route for myocardium because chamber blood cannot nourish thick muscle walls directly."},{"star":false,"html":"<strong>Right atrium</strong> receives blood from systemic veins → right ventricle is filled for pulmonary pumping."},{"star":false,"html":"<strong>Left atrium</strong> receives oxygenated pulmonary venous blood → left ventricle is filled for systemic pumping."},{"star":false,"html":"<strong>Atria</strong> mainly receive and top up blood, whereas ventricles generate the pressure that drives blood through vessels."},{"star":false,"html":"<strong>Tricuspid and mitral valves</strong> permit atrium-to-ventricle flow when atrial pressure exceeds ventricular pressure."},{"star":false,"html":"<strong>Pulmonary and aortic valves</strong> permit ventricular outflow when ventricular pressure exceeds the downstream arterial pressure."},{"star":true,"html":"<strong>Passive valve movement</strong> follows pressure gradients; valve leaflets do not actively contract to open or close."},{"star":false,"html":"<strong>Arteries and veins</strong> are defined by direction: arteries carry blood away from heart; veins return it, regardless of oxygen content."},{"star":false,"html":"<strong>Left ventricular wall thickness</strong> is greater because systemic resistance needs higher pressure, not because the left ventricle pumps more volume."},{"star":false,"html":"<strong>Low pulmonary circuit pressure</strong> protects thin alveolar capillaries from excessive filtration and pulmonary oedema."},{"star":false,"html":"<strong>Systole and diastole</strong> describe a chamber’s contraction/pressure generation and relaxation/filling, respectively."},{"star":false,"html":"<strong>Atrial systole</strong> occurs near the end of ventricular diastole → the atrial kick completes ventricular filling."},{"star":false,"html":"<strong>Cardiac electrical activation</strong> normally travels SA node → AV node → His–Purkinje system before organised ventricular contraction."},{"star":false,"html":"<strong>Electrical-before-mechanical sequence</strong> allows depolarisation to trigger contraction, followed by pressure changes, valve action and blood movement."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Resting output from each ventricle</td>\n  <td>About 5 L/min</td>\n  <td>Right and left outputs match in circuits connected in series.</td>\n</tr>\n<tr>\n  <td>Systemic left ventricular systolic pressure</td>\n  <td>About 120 mmHg</td>\n  <td>Reflects high systemic vascular resistance.</td>\n</tr>\n<tr>\n  <td>Right ventricular/pulmonary systolic pressure</td>\n  <td>About 25 mmHg</td>\n  <td>Reflects low-resistance pulmonary flow.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Whole-body circulation</strong>: Systemic veins → right atrium → right ventricle → pulmonary artery → lung capillaries → pulmonary veins → left atrium → left ventricle → systemic arteries.</li>\n<li><strong>Cardiac pumping sequence</strong>: SA node fires → atria depolarise and contract → AV delay permits ventricular filling → His–Purkinje activates ventricles → pressure rises → outflow valves open.</li>\n<li><strong>Valve operation</strong>: Upstream pressure exceeds downstream pressure → valve opens → blood flows; gradient reverses → valve shuts → backflow is prevented.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Systemic circulation</strong></th>\n  <th><strong>Pulmonary circulation</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Pump origin</td>\n  <td>Left ventricle.</td>\n  <td>Right ventricle.</td>\n</tr>\n<tr>\n  <td>Main purpose</td>\n  <td>Deliver oxygen/nutrients to tissues.</td>\n  <td>Oxygenate blood in lungs.</td>\n</tr>\n<tr>\n  <td>Pressure/resistance</td>\n  <td>Relatively high.</td>\n  <td>Relatively low.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Artery</strong></th>\n  <th><strong>Vein</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Defining direction</td>\n  <td>Away from heart.</td>\n  <td>Towards heart.</td>\n</tr>\n<tr>\n  <td>Oxygen content</td>\n  <td>Often high, except pulmonary/umbilical exceptions.</td>\n  <td>Often low, except pulmonary/umbilical exceptions.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Left ventricle</strong> pumps more blood each minute because its wall is thicker → Truth: Both ventricles have equal long-term output but different pressure workloads.</li>\n<li>Trap: <strong>Pulmonary artery</strong> must contain oxygenated blood because it is an artery → Truth: Arteries are named by direction; pulmonary arteries carry deoxygenated blood.</li>\n<li>Trap: <strong>Heart valves</strong> need their own muscle contraction to open → Truth: Pressure differences move their leaflets passively.</li>\n<li>Trap: <strong>Atrial systole</strong> takes place while ventricles are already ejecting → Truth: Atrial contraction tops up ventricles near the end of their diastole.</li>\n</ul>\n"},{"slug":"cardiac-muscle","must":[{"star":true,"html":"<strong>Cardiac muscle cells</strong> are striated, branched and electrically connected → they generate rhythmic coordinated contractions rather than isolated twitches."},{"star":false,"html":"<strong>Intercalated discs</strong> join adjacent myocytes mechanically and electrically so contractile force and depolarisation spread throughout myocardium."},{"star":false,"html":"<strong>Gap junctions</strong> pass ionic current between cells → electrical signals spread directly between connected cardiac fibres."},{"star":false,"html":"<strong>Desmosomes</strong> protect intercellular attachments from tearing during repeated contraction."},{"star":false,"html":"<strong>Fascia adherens</strong> anchors actin to cell junctions → contractile force passes to neighbouring myocytes."},{"star":false,"html":"<strong>Functional syncytium</strong> means atrial or ventricular cells behave as an electrically coordinated unit despite remaining separate cells."},{"star":false,"html":"<strong>Fibrous atrioventricular skeleton</strong> electrically insulates atria from ventricles → normal impulses cross chiefly via the AV conducting pathway."},{"star":true,"html":"<strong>Ventricular action-potential phase 0</strong> rapidly depolarises working muscle because fast Na⁺ channels open and sodium enters."},{"star":false,"html":"<strong>Ventricular phase 1</strong> is brief early repolarisation following fast sodium-channel inactivation."},{"star":true,"html":"<strong>Ventricular phase 2 plateau</strong> persists because inward L-type Ca²⁺ current roughly balances outward K⁺ current."},{"star":false,"html":"<strong>Ventricular phase 3</strong> repolarises myocytes because K⁺ efflux dominates as calcium influx declines."},{"star":false,"html":"<strong>Ventricular phase 4</strong> maintains a stable resting membrane potential until the next activating impulse."},{"star":false,"html":"<strong>ST segment</strong> corresponds largely to the ventricular action-potential plateau, when myocardium is depolarised but still mechanically active."},{"star":true,"html":"<strong>Calcium-induced calcium release</strong> begins when Ca²⁺ enters through L-type channels and opens ryanodine receptor RyR2 on sarcoplasmic reticulum."},{"star":false,"html":"<strong>Cytosolic calcium rise</strong> permits Ca²⁺ binding to troponin C → tropomyosin moves → actin–myosin cross-bridges form."},{"star":false,"html":"<strong>Cross-bridge cycling</strong> generates force when myosin repeatedly interacts with actin using ATP."},{"star":false,"html":"<strong>SERCA2a</strong> uses ATP to pump cytosolic Ca²⁺ back into the sarcoplasmic reticulum → muscle relaxation becomes possible."},{"star":false,"html":"<strong>Na⁺–Ca²⁺ exchanger (NCX)</strong> removes intracellular Ca²⁺ across the sarcolemma → helps terminate contraction."},{"star":false,"html":"<strong>Phospholamban</strong> normally inhibits SERCA; its phosphorylation releases inhibition and accelerates calcium reuptake."},{"star":false,"html":"<strong>ATP dependence of relaxation</strong> means calcium removal fails when energy supply is inadequate, prolonging contractile dysfunction."},{"star":false,"html":"<strong>Long cardiac refractory period</strong> overlaps most of contraction → rapid repetitive stimuli cannot cause sustained ventricular tetanus."},{"star":false,"html":"<strong>Prevention of tetanus</strong> preserves time for ventricular relaxation, filling and repeated effective ejection."},{"star":false,"html":"<strong>Sympathetic β₁ activation</strong> increases cAMP and PKA → Ca²⁺ entry/release rise, increasing force and accelerating relaxation."},{"star":false,"html":"<strong>Positive inotropy</strong> means stronger contraction at the same initial fibre stretch or ventricular filling."},{"star":false,"html":"<strong>Positive lusitropy</strong> means faster myocardial relaxation through more rapid intracellular calcium removal."},{"star":false,"html":"<strong>Positive chronotropy</strong> means increased heart rate through faster pacemaker firing."},{"star":false,"html":"<strong>Vagal stimulation</strong> primarily slows SA nodal firing and atrial contraction, with much less direct effect on ventricular force."},{"star":false,"html":"<strong>Phosphodiesterase inhibition by xanthines</strong> reduces cAMP breakdown → stronger sympathetic-like intracellular signalling can develop."},{"star":false,"html":"<strong>Impaired SERCA function</strong> delays calcium clearance → relaxation becomes slower and diastolic filling pressure may rise."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Principal phases of a ventricular myocyte action potential</td>\n  <td>0–4</td>\n  <td>Fast depolarisation, early repolarisation, plateau, repolarisation and resting phase.</td>\n</tr>\n<tr>\n  <td>Functional cardiac muscle syncytia</td>\n  <td>2</td>\n  <td>Atrial and ventricular units are electrically insulated from each other.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Excitation–contraction coupling</strong>: Ventricular action potential → L-type calcium entry → RyR2-mediated SR calcium release → troponin C binding → cross-bridge cycling → ventricular contraction.</li>\n<li><strong>Relaxation</strong>: Calcium channels close and potassium repolarises cell → SERCA returns calcium to SR and NCX expels calcium → troponin releases calcium → cross-bridges cease → muscle relaxes.</li>\n<li><strong>Sympathetic stimulation</strong>: Noradrenaline activates β₁ → cAMP/PKA signalling rises → calcium entry and SR cycling increase → contraction becomes stronger and relaxation faster.</li>\n<li><strong>Tetanus prevention</strong>: Sustained plateau prolongs refractory period → cardiac muscle cannot be re-excited throughout most of systole → relaxation and diastolic filling remain possible.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Working ventricular myocyte</strong></th>\n  <th><strong>SA nodal pacemaker cell</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Upstroke</td>\n  <td>Fast Na⁺ entry.</td>\n  <td>Predominantly Ca²⁺ entry.</td>\n</tr>\n<tr>\n  <td>Phase 2</td>\n  <td>Prolonged plateau.</td>\n  <td>No comparable ventricular plateau.</td>\n</tr>\n<tr>\n  <td>Resting phase</td>\n  <td>Relatively stable phase 4.</td>\n  <td>Spontaneously depolarising phase 4.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Inotropy</strong></th>\n  <th><strong>Lusitropy</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Property</td>\n  <td>Strength of contraction at equal preload.</td>\n  <td>Speed of relaxation.</td>\n</tr>\n<tr>\n  <td>Main Ca²⁺ relationship</td>\n  <td>More available activator calcium increases force.</td>\n  <td>Faster calcium removal speeds relaxation.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Gap junctions</strong> mainly prevent cells tearing → Truth: They transmit current; desmosomes and fascia adherens provide mechanical attachment.</li>\n<li>Trap: <strong>Phase 2 plateau</strong> means cardiac muscle is electrically at rest → Truth: Ventricular cells remain depolarised while Ca²⁺ entry supports contraction.</li>\n<li>Trap: <strong>Calcium influx alone</strong> supplies all activator calcium → Truth: Entering Ca²⁺ triggers much larger SR release through RyR2.</li>\n<li>Trap: <strong>SERCA</strong> sends calcium out of the cell → Truth: SERCA pumps calcium into SR; NCX helps extrude it across the membrane.</li>\n<li>Trap: <strong>Cardiac muscle</strong> can sustain tetanus like skeletal muscle → Truth: Its long refractory period prevents fusion of ventricular contractions.</li>\n<li>Trap: <strong>Positive inotropy</strong> necessarily means increased end-diastolic volume → Truth: It describes increased force at the same preload.</li>\n</ul>\n"},{"slug":"cardiac-conduction","must":[{"star":true,"html":"<strong>SA node</strong> normally starts each heartbeat because its spontaneous diastolic depolarisation reaches threshold faster than other pacemaker tissues."},{"star":false,"html":"<strong>SA node position</strong> is near the junction of superior vena cava and right atrium."},{"star":true,"html":"<strong>Normal conduction pathway</strong> is SA node → atrial myocardium → AV node → His bundle → right/left bundle branches → Purkinje fibres → ventricles."},{"star":false,"html":"<strong>Automaticity</strong> means specialised pacemaker cells depolarise spontaneously; autonomic nerves modify their rate rather than create each impulse."},{"star":false,"html":"<strong>Pacemaker phase 4</strong> spontaneously rises towards threshold, partly through funny current activated at negative membrane potentials."},{"star":false,"html":"<strong>Funny current (If)</strong> allows inward depolarising current during the SA nodal pacemaker phase → the next spontaneous impulse is initiated."},{"star":false,"html":"<strong>SA nodal phase 0</strong> is mainly L-type Ca²⁺ entry rather than the fast sodium upstroke of working ventricular myocytes."},{"star":false,"html":"<strong>SA nodal phase 3</strong> repolarises as potassium exits; a ventricular-style phase 2 plateau is absent."},{"star":false,"html":"<strong>Fastest-pacemaker dominance</strong> suppresses slower automatic foci because SA node impulses reach and reset them before they fire."},{"star":false,"html":"<strong>AV junction escape rhythm</strong> can take over after SA node failure but typically produces a slower ventricular rate."},{"star":false,"html":"<strong>Ventricular escape rhythm</strong> is slower again because distal conducting tissues depolarise spontaneously at a lower frequency."},{"star":true,"html":"<strong>AV nodal delay</strong> slows atrium-to-ventricle conduction so atria can finish filling ventricles before ventricular contraction begins."},{"star":false,"html":"<strong>AV nodal location</strong> is in the lower right atrial septal region near the tricuspid valve."},{"star":false,"html":"<strong>PR interval</strong> spans start of atrial depolarisation to start of ventricular depolarisation and includes atrial conduction plus AV delay."},{"star":true,"html":"<strong>His–Purkinje rapid conduction</strong> synchronises ventricular activation → ventricular pressure rises efficiently rather than in scattered contractions."},{"star":false,"html":"<strong>Purkinje conducting speed</strong> is much greater than AV nodal speed because specialised fibres transmit impulses rapidly through ventricles."},{"star":false,"html":"<strong>Intrinsic SA nodal rate</strong> is faster than the resting pulse because baseline vagal inhibition slows pacemaker firing."},{"star":false,"html":"<strong>Vagal M₂ stimulation</strong> increases pacemaker K⁺ conductance and reduces If/cAMP → phase 4 becomes less steep and rate falls."},{"star":false,"html":"<strong>Sympathetic β₁ stimulation</strong> increases cAMP and pacemaker depolarising currents → phase 4 steepens and heart rate rises."},{"star":false,"html":"<strong>Atropine</strong> blocks vagal muscarinic signalling → resting heart rate rises because the normal vagal brake is removed."},{"star":false,"html":"<strong>First-degree AV block</strong> delays conduction → PR interval is prolonged but every atrial impulse reaches ventricles."},{"star":false,"html":"<strong>Second-degree AV block</strong> intermittently fails conduction → some P waves are not followed by ventricular QRS complexes."},{"star":false,"html":"<strong>Third-degree AV block</strong> stops atrial-to-ventricle conduction → atrial and ventricular rhythms become independent."},{"star":false,"html":"<strong>Escape pacemakers</strong> protect against complete asystole after proximal failure but often generate slow, inadequate ventricular rates."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Intrinsic SA nodal rate</td>\n  <td>About 100 beats/min</td>\n  <td>Vagal tone reduces the resting heart rate below this.</td>\n</tr>\n<tr>\n  <td>Resting heart rate with vagal tone</td>\n  <td>About 60–80 beats/min</td>\n  <td>Vagal inhibition normally limits pacemaker discharge.</td>\n</tr>\n<tr>\n  <td>AV junction escape rate</td>\n  <td>About 40–60 beats/min</td>\n  <td>Backup pacemaker is slower than SA node.</td>\n</tr>\n<tr>\n  <td>Ventricular escape rate</td>\n  <td>About 20–40 beats/min</td>\n  <td>Distal backup pacemaker may not maintain adequate perfusion.</td>\n</tr>\n<tr>\n  <td>AV node conduction velocity</td>\n  <td>About 0.05 m/s</td>\n  <td>Slow propagation allows atrial emptying before ventricular systole.</td>\n</tr>\n<tr>\n  <td>Purkinje conduction velocity</td>\n  <td>About 2–4 m/s</td>\n  <td>Very rapid activation synchronises ventricular contraction.</td>\n</tr>\n<tr>\n  <td>Normal PR interval</td>\n  <td>0.12–0.20 seconds</td>\n  <td>Measures atrial-to-ventricular electrical activation time.</td>\n</tr>\n<tr>\n  <td>Normal QRS duration</td>\n  <td>About 0.06–0.10 seconds (lecture ECG values)</td>\n  <td>Represents rapid ventricular depolarisation.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Normal beat sequence</strong>: SA node fires → atria depolarise and contract → AV node delays signal → His/bundle branches/Purkinje distribute impulse → ventricles depolarise together and contract.</li>\n<li><strong>Pacemaker automaticity</strong>: SA nodal phase 3 ends → If contributes to phase 4 rise → threshold opens Ca²⁺ channels → nodal phase 0 → K⁺ exit restores negative potential.</li>\n<li><strong>Autonomic chronotropy</strong>: Sympathetic β₁ increases cAMP → phase 4 rises faster → earlier impulse; vagal M₂ increases K⁺ and lowers cAMP → slower phase 4 → later impulse.</li>\n<li><strong>Complete heart block</strong>: AV conduction stops → SA node still drives atria → distal escape focus drives ventricles independently → the ventricles beat slowly and independently of the atria.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>SA node</strong></th>\n  <th><strong>AV node</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Usual role</td>\n  <td>Dominant pacemaker.</td>\n  <td>Delays atrial-to-ventricular conduction.</td>\n</tr>\n<tr>\n  <td>Dominant property</td>\n  <td>Fastest automaticity.</td>\n  <td>Slow transmission.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>First-degree block</strong></th>\n  <th><strong>Third-degree block</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Impulse transmission</td>\n  <td>Every atrial impulse arrives late.</td>\n  <td>No atrial impulses conduct through AV system.</td>\n</tr>\n<tr>\n  <td>ECG clue</td>\n  <td>Prolonged PR with every P followed by QRS.</td>\n  <td>Independent P and QRS rhythms.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Autonomic nerves</strong> are required to initiate SA nodal firing → Truth: Automaticity is intrinsic; autonomic nerves alter discharge rate.</li>\n<li>Trap: <strong>SA nodal upstroke</strong> uses fast sodium channels exactly like ventricles → Truth: Nodal phase 0 is driven mainly by calcium entry.</li>\n<li>Trap: <strong>AV delay</strong> means the heart wastes time before ventricular filling → Truth: It permits atrial contraction to complete filling.</li>\n<li>Trap: <strong>Purkinje fibres</strong> are slow to allow sequential ventricular contraction → Truth: They conduct rapidly to coordinate both ventricles.</li>\n<li>Trap: <strong>First-degree heart block</strong> drops some atrial impulses → Truth: Every impulse conducts but the PR interval is prolonged.</li>\n<li>Trap: <strong>Complete AV block</strong> means the atria stop firing → Truth: Atria may keep following SA rhythm while ventricular escape rhythm is independent.</li>\n</ul>\n"},{"slug":"cardiac-cycle","must":[{"star":true,"html":"<strong>Cardiac cycle</strong> is the ordered sequence of electrical activation, muscle contraction/relaxation, pressure changes, valve movement and volume changes."},{"star":false,"html":"<strong>Ventricular diastole</strong> includes filling and relaxation, while atrial systole occurs near its end."},{"star":false,"html":"<strong>Atrial diastole</strong> overlaps ventricular systole and much of ventricular diastole because atria relax and refill for most of each beat."},{"star":false,"html":"<strong>Joint cardiac diastole</strong> occurs when both atria and ventricles are relaxed together during part of passive ventricular filling."},{"star":true,"html":"<strong>Passive heart valves</strong> open when upstream pressure exceeds downstream pressure and close when the pressure gradient reverses."},{"star":false,"html":"<strong>Papillary muscles</strong> prevent AV valve leaflets everting during ventricular systole; they do not actively close the valves."},{"star":false,"html":"<strong>Rapid ventricular filling</strong> begins when ventricular pressure falls below atrial pressure and AV valves open."},{"star":false,"html":"<strong>Diastasis</strong> is a slower filling interval as the atrium-to-ventricle pressure gradient becomes small."},{"star":false,"html":"<strong>Atrial kick</strong> adds the final portion of ventricular filling as the P wave triggers atrial contraction."},{"star":false,"html":"<strong>Atrial contraction</strong> contributes more to filling when ventricular compliance is reduced or diastole is shortened by tachycardia."},{"star":true,"html":"<strong>Isovolumetric contraction</strong> starts when mitral/tricuspid valves close, creating S1; all valves remain shut while ventricular pressure rises at fixed EDV."},{"star":false,"html":"<strong>AV valve bulging</strong> during early ventricular contraction causes the atrial c wave as pressure pushes the closed leaflet backwards."},{"star":false,"html":"<strong>Semilunar valve opening</strong> occurs only after ventricular pressure exceeds aortic or pulmonary artery pressure."},{"star":false,"html":"<strong>Rapid ejection</strong> initially expels blood quickly because ventricular pressure and outflow gradients are high."},{"star":false,"html":"<strong>Reduced ejection</strong> follows rapid ejection as ventricular force declines and outflow slows despite continuing systole."},{"star":false,"html":"<strong>Ventricular repolarisation</strong> appears as the T wave during later ejection before the semilunar valves close."},{"star":false,"html":"<strong>Protodiastole</strong> is the short transition after ejection when ventricular pressure falls towards the arterial pressure."},{"star":true,"html":"<strong>Semilunar valve closure</strong> follows slight arterial backflow when ventricular pressure falls below arterial pressure → S2 marks the end of ejection."},{"star":false,"html":"<strong>Aortic dicrotic notch</strong> reflects transient pressure disturbance associated with aortic valve closure and arterial elastic recoil."},{"star":false,"html":"<strong>Isovolumetric relaxation</strong> occurs with all four valves shut → ventricular pressure falls while volume remains at ESV."},{"star":false,"html":"<strong>Ventricular filling restarts</strong> when pressure becomes lower than atrial pressure → mitral/tricuspid valves open passively."},{"star":false,"html":"<strong>End-diastolic volume (EDV)</strong> is the ventricular volume immediately before contraction, after atrial filling ends."},{"star":false,"html":"<strong>End-systolic volume (ESV)</strong> is blood remaining after ventricular ejection ends."},{"star":false,"html":"<strong>Stroke volume</strong> equals EDV minus ESV → reflects the volume pumped out by one ventricle per beat."},{"star":false,"html":"<strong>Ejection fraction</strong> equals stroke volume divided by EDV → gauges the fraction of filled blood ejected each beat."},{"star":false,"html":"<strong>Atrial a and c waves</strong> reflect atrial contraction and closed AV valve bulging during early ventricular systole, respectively."},{"star":false,"html":"<strong>Atrial x descent</strong> reflects atrial relaxation and downward AV ring movement during ventricular systole."},{"star":false,"html":"<strong>Atrial v wave</strong> forms as the atrium fills behind a closed AV valve during ventricular contraction."},{"star":false,"html":"<strong>Atrial y descent</strong> begins when the AV valve opens and atrial blood empties into the ventricle."},{"star":false,"html":"<strong>P wave</strong> reflects atrial depolarisation preceding atrial mechanical contraction."},{"star":false,"html":"<strong>QRS complex</strong> reflects ventricular depolarisation preceding isovolumetric contraction and S1."},{"star":false,"html":"<strong>T wave</strong> reflects ventricular repolarisation during late ejection, before ventricular pressure and arterial flow fall enough for S2."},{"star":false,"html":"<strong>Wiggers diagram</strong> aligns ECG, chamber pressures, arterial pressure, ventricular volume and sounds to one shared time axis."},{"star":false,"html":"<strong>Pressure-curve intersection</strong> identifies each valve opening or closing because valves respond to which chamber has higher pressure."},{"star":false,"html":"<strong>Right ventricular ejection</strong> begins at lower pressure than left ventricular ejection because pulmonary arterial pressure is much lower."},{"star":false,"html":"<strong>Physiological S2 splitting</strong> widens on inspiration as right-sided emptying lasts longer and P2 is delayed relative to A2."},{"star":false,"html":"<strong>Faster heart rates</strong> shorten diastole disproportionately → passive filling and left coronary perfusion time can decrease."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Typical resting cardiac cycle</td>\n  <td>About 0.8 seconds</td>\n  <td>Corresponds to roughly 75 beats/min.</td>\n</tr>\n<tr>\n  <td>Time both atria and ventricles are relaxed</td>\n  <td>About 0.4 seconds in a 0.8-second cycle</td>\n  <td>Passive filling overlaps atrial diastole.</td>\n</tr>\n<tr>\n  <td>Passive ventricular filling proportion in lecture</td>\n  <td>About 70%</td>\n  <td>Most filling usually needs no atrial contraction.</td>\n</tr>\n<tr>\n  <td>Atrial filling contribution in lecture</td>\n  <td>About 30%</td>\n  <td>Atrial kick completes filling; proportion varies with conditions.</td>\n</tr>\n<tr>\n  <td>Approximate aortic pressure needed for LV ejection</td>\n  <td>80 mmHg</td>\n  <td>Left semilunar valve opens when LV pressure exceeds aortic diastolic pressure.</td>\n</tr>\n<tr>\n  <td>Approximate pulmonary pressure needed for RV ejection</td>\n  <td>10 mmHg</td>\n  <td>Right semilunar valve opens at lower pressure.</td>\n</tr>\n<tr>\n  <td>Typical EDV in lecture</td>\n  <td>About 130 mL</td>\n  <td>Ventricular blood volume at end of filling.</td>\n</tr>\n<tr>\n  <td>Normal interval between P and QRS onset</td>\n  <td>0.12–0.20 seconds</td>\n  <td>Electrical delay allows atrial emptying before ventricular systole.</td>\n</tr>\n<tr>\n  <td>Stroke-volume relation</td>\n  <td>SV = EDV − ESV</td>\n  <td>Defines the volume ejected in one beat.</td>\n</tr>\n<tr>\n  <td>Ejection fraction relation</td>\n  <td>EF = SV ÷ EDV × 100%</td>\n  <td>Expresses the ejected fraction of end-diastolic volume.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Filling and atrial systole</strong>: Ventricles relax → AV valves open → rapid filling then diastasis → SA node fires and P wave appears → atria contract → EDV is reached.</li>\n<li><strong>Isovolumetric contraction and ejection</strong>: QRS activates ventricles → rising ventricular pressure closes AV valves (S1) → all valves shut and volume fixed → pressure exceeds arterial pressure → rapid then reduced ejection lowers volume.</li>\n<li><strong>Semilunar closure and relaxation</strong>: Ventricular repolarisation progresses → ventricular pressure falls below arterial pressure → semilunar valves close (S2) → all valves shut as pressure falls at ESV → AV valves reopen.</li>\n<li><strong>Wiggers interpretation</strong>: Identify ECG event → find ensuing ventricular pressure change → compare upstream/downstream pressure curves → identify valve state → determine ventricular-volume change and heart sound.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Isovolumetric contraction</strong></th>\n  <th><strong>Isovolumetric relaxation</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Ventricular pressure</td>\n  <td>Rises sharply.</td>\n  <td>Falls sharply.</td>\n</tr>\n<tr>\n  <td>Ventricular volume</td>\n  <td>Fixed at EDV.</td>\n  <td>Fixed at ESV.</td>\n</tr>\n<tr>\n  <td>Valve state</td>\n  <td>All four valves closed.</td>\n  <td>All four valves closed.</td>\n</tr>\n<tr>\n  <td>Associated sound</td>\n  <td>Follows S1 from AV valve closure.</td>\n  <td>Follows S2 from semilunar closure.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Atrial a wave</strong></th>\n  <th><strong>Atrial v wave</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Cause</td>\n  <td>Atrial contraction.</td>\n  <td>Atrial filling while AV valve remains closed.</td>\n</tr>\n<tr>\n  <td>Timing</td>\n  <td>Late ventricular diastole.</td>\n  <td>Ventricular systole.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Isovolumetric phase</strong> means ventricular pressure stays fixed → Truth: Volume stays constant while pressure rises or falls with all valves closed.</li>\n<li>Trap: <strong>Semilunar valves open</strong> because atria contract → Truth: They open only when ventricular pressure exceeds arterial pressure.</li>\n<li>Trap: <strong>Papillary muscles</strong> open the AV valves → Truth: They prevent prolapse of valves already forced shut by ventricular pressure.</li>\n<li>Trap: <strong>The entire ejection phase</strong> has the same high flow → Truth: Ejection begins rapidly and then becomes reduced.</li>\n<li>Trap: <strong>T wave</strong> occurs only after aortic valve closure → Truth: Ventricular repolarisation develops during reduced ejection before S2.</li>\n<li>Trap: <strong>Atrial v wave</strong> equals atrial systole → Truth: It reflects atrial venous filling behind the shut AV valve.</li>\n<li>Trap: <strong>S2 widening on inspiration</strong> is due to A2 delay → Truth: Increased right ventricular filling chiefly delays P2.</li>\n</ul>\n"},{"slug":"heart-sounds","must":[{"star":true,"html":"<strong>S1</strong> is produced by mitral/tricuspid valve closure and resulting vibration when ventricular systole begins."},{"star":true,"html":"<strong>S2</strong> is produced by aortic/pulmonary valve closure and resulting vibration at the onset of ventricular diastole."},{"star":false,"html":"<strong>Heart sounds</strong> chiefly reflect vibration from abruptly changing blood flow rather than valve leaflets striking like solid objects."},{"star":false,"html":"<strong>Valve opening</strong> is normally silent because opening does not suddenly stop a moving blood column."},{"star":false,"html":"<strong>S1–S2 interval</strong> spans ventricular systole, while S2–next S1 spans ventricular diastole."},{"star":false,"html":"<strong>Apex auscultation</strong> generally makes S1 louder, whereas the cardiac base generally makes S2 more prominent."},{"star":true,"html":"<strong>Physiological S2 splitting</strong> occurs on inspiration because greater right-sided filling delays pulmonary valve closure (P2) relative to A2."},{"star":false,"html":"<strong>Expiration</strong> usually narrows normal S2 splitting because the right ventricular ejection delay becomes smaller."},{"star":false,"html":"<strong>S3</strong> occurs just after S2 during rapid ventricular filling → may be normal in youth but suggests volume overload in older adults."},{"star":false,"html":"<strong>S4</strong> occurs immediately before S1 when atrial contraction forces blood into a stiff, non-compliant ventricle."},{"star":false,"html":"<strong>Atrial fibrillation</strong> abolishes the true S4 mechanism because organised atrial contraction is absent."},{"star":false,"html":"<strong>Slow heart rate</strong> may soften S1 because AV leaflets drift nearer closure before the ventricle contracts."},{"star":false,"html":"<strong>High aortic pressure</strong> may produce a loud aortic closure component (A2) as the valve closes under higher pressure."},{"star":false,"html":"<strong>High pulmonary pressure</strong> can accentuate P2 because increased pulmonary artery pressure strengthens semilunar closure vibration."},{"star":false,"html":"<strong>Heart-sound loudness</strong> does not by itself measure lesion severity because valve mobility and many haemodynamic factors affect it."},{"star":true,"html":"<strong>Murmur</strong> is audible vibration from turbulent blood flow caused by narrowed valves, leaking valves or high flow through normal structures."},{"star":false,"html":"<strong>Stenotic valve murmur</strong> occurs while the narrowed valve should be open → blood accelerates through a restricted forward opening."},{"star":false,"html":"<strong>Regurgitant murmur</strong> occurs while a valve should be closed → abnormal backflow creates a jet and turbulent vibrations."},{"star":false,"html":"<strong>Aortic/pulmonary stenosis</strong> causes systolic murmurs because semilunar valves should be open during ventricular ejection."},{"star":false,"html":"<strong>Mitral/tricuspid regurgitation</strong> causes systolic murmurs because AV valves should be closed during ventricular systole."},{"star":false,"html":"<strong>Mitral/tricuspid stenosis</strong> causes diastolic murmurs because AV valves should allow ventricular filling during diastole."},{"star":false,"html":"<strong>Aortic/pulmonary regurgitation</strong> causes diastolic murmurs because semilunar valves should be closed during ventricular filling."},{"star":false,"html":"<strong>High-output flow murmurs</strong> can arise with anaemia because increased velocity and low blood viscosity favour turbulence through normal valves."},{"star":false,"html":"<strong>Aortic listening area</strong> is the second right intercostal space near the sternum, where aortic sounds transmit best."},{"star":false,"html":"<strong>Pulmonary listening area</strong> is the second left intercostal space near the sternum, where P2 and pulmonary murmurs transmit."},{"star":false,"html":"<strong>Tricuspid listening area</strong> is the lower left sternal border, rather than the valve's exact anatomical position."},{"star":false,"html":"<strong>Mitral listening area</strong> is near the left ventricular apex, where mitral sounds are best heard."},{"star":false,"html":"<strong>Vascular bruits</strong> also arise from turbulent blood due to narrowing, aneurysm or abnormal vascular connections."},{"star":false,"html":"<strong>Patent ductus arteriosus</strong> causes a continuous murmur because aortic pressure exceeds pulmonary artery pressure during systole and diastole."},{"star":false,"html":"<strong>Arteriovenous fistula</strong> can produce a bruit because abnormal low-resistance communication creates fast turbulent flow."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Aortic valve listening site</td>\n  <td>2nd right intercostal space</td>\n  <td>Useful for A2 and aortic murmurs.</td>\n</tr>\n<tr>\n  <td>Pulmonary valve listening site</td>\n  <td>2nd left intercostal space</td>\n  <td>Useful for P2 and pulmonary murmurs.</td>\n</tr>\n<tr>\n  <td>Heart-sound timing</td>\n  <td>S1, S2, S3, S4</td>\n  <td>Distinguishes valve closure from rapid filling and atrial kick.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>S1 and S2 generation</strong>: Ventricular pressure exceeds atrial pressure → AV valves close and S1 occurs → ejection follows → ventricular pressure falls below arterial pressure → semilunar valves close and S2 occurs.</li>\n<li><strong>Normal S2 splitting</strong>: Inspiration lowers intrathoracic pressure → right venous return increases → right ventricular ejection persists longer → pulmonary closure P2 occurs later than A2.</li>\n<li><strong>Valve murmur prediction</strong>: Identify valve → decide when it should be open or shut → stenosis produces turbulence while open, regurgitation while shut → infer systolic or diastolic timing.</li>\n<li><strong>Extra heart sounds</strong>: Rapid early diastolic filling vibrates ventricle → S3; atrial contraction against a stiff ventricle causes late diastolic vibration → S4.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>S3</strong></th>\n  <th><strong>S4</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Timing</td>\n  <td>Early diastole after S2.</td>\n  <td>Late diastole just before S1.</td>\n</tr>\n<tr>\n  <td>Mechanism</td>\n  <td>Rapid ventricular filling/volume state.</td>\n  <td>Atrial kick into stiff ventricular chamber.</td>\n</tr>\n<tr>\n  <td>Normal possibility</td>\n  <td>May be physiological in young people.</td>\n  <td>Generally suggests reduced ventricular compliance.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Valve stenosis</strong></th>\n  <th><strong>Valve regurgitation</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Mechanical defect</td>\n  <td>Forward opening is narrowed.</td>\n  <td>Closed valve leaks backwards.</td>\n</tr>\n<tr>\n  <td>Murmur timing logic</td>\n  <td>When valve should be open.</td>\n  <td>When valve should be closed.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>S1</strong> is caused by aortic and pulmonary valve closure → Truth: S1 follows mitral/tricuspid closure; semilunar closure produces S2.</li>\n<li>Trap: <strong>Inspiration splits S2</strong> by delaying A2 → Truth: P2 is usually delayed by greater right ventricular filling and ejection duration.</li>\n<li>Trap: <strong>S3</strong> is always pathological → Truth: It may be physiological in young people but concerning in older volume-overloaded patients.</li>\n<li>Trap: <strong>S4</strong> persists in atrial fibrillation → Truth: S4 requires organised atrial contraction.</li>\n<li>Trap: <strong>All systolic murmurs</strong> are from stenotic valves → Truth: AV valve regurgitation also produces systolic turbulence.</li>\n<li>Trap: <strong>Auscultation areas</strong> exactly overlie the anatomical valve leaflets → Truth: These are surface positions where each transmitted sound is best heard.</li>\n<li>Trap: <strong>Patent ductus murmur</strong> lasts only in systole → Truth: Aortic-to-pulmonary driving pressure persists during both phases.</li>\n</ul>\n"},{"slug":"cardiac-output","must":[{"star":true,"html":"<strong>Cardiac output (CO)</strong> is blood pumped by one ventricle each minute → it equals heart rate multiplied by stroke volume."},{"star":false,"html":"<strong>Equal ventricular outputs</strong> are required over time because the pulmonary and systemic circuits lie in series."},{"star":false,"html":"<strong>Cardiac index</strong> adjusts output for body surface area → comparisons between differently sized people become more meaningful."},{"star":false,"html":"<strong>Heart rate alone</strong> cannot predict cardiac output because stroke volume may fall when high rates shorten ventricular filling."},{"star":true,"html":"<strong>Stroke volume</strong> equals end-diastolic minus end-systolic volume → blood remaining after ejection is excluded from pumped volume."},{"star":false,"html":"<strong>Preload</strong> describes ventricular stretch just before contraction and is commonly estimated by EDV."},{"star":false,"html":"<strong>Afterload</strong> describes the pressure/resistance the ventricle must overcome during ejection, including aortic pressure for left ventricle."},{"star":false,"html":"<strong>Contractility</strong> describes intrinsic myocardial force at the same preload, independently of how much the ventricle initially fills."},{"star":true,"html":"<strong>Frank–Starling mechanism</strong> increases stroke volume when venous return and filling rise because stretching sarcomeres improves force development."},{"star":false,"html":"<strong>Sarcomere stretch</strong> improves actin–myosin overlap and calcium sensitivity within normal filling ranges → stronger ejection follows."},{"star":false,"html":"<strong>Output matching</strong> occurs because ventricles eject more when more blood returns, preventing sustained blood buildup in either circulation."},{"star":false,"html":"<strong>Movement along a Starling curve</strong> represents changed preload while the heart's intrinsic contractility is held constant."},{"star":false,"html":"<strong>Upward shift of a Starling curve</strong> represents increased contractility → more output at the same filling pressure or EDV."},{"star":false,"html":"<strong>Downward Starling-curve shift</strong> reflects weaker myocardium → the same filling pressure gives less stroke volume."},{"star":false,"html":"<strong>Afterload increase</strong> makes ejection harder → stroke volume can fall and ESV rise even when preload stays unchanged."},{"star":false,"html":"<strong>Greater blood volume</strong> increases venous return and EDV → stroke volume can increase by Frank–Starling physiology."},{"star":false,"html":"<strong>Venoconstriction</strong> mobilises stored venous blood → higher central filling supports EDV and output."},{"star":false,"html":"<strong>Skeletal-muscle pump</strong> returns leg blood to the heart during movement → EDV may increase."},{"star":false,"html":"<strong>Inspiration</strong> usually supports systemic venous return to the right heart through lower thoracic pressure."},{"star":false,"html":"<strong>Atrial contraction</strong> boosts EDV, especially when ventricular filling is impaired or the heart beats rapidly."},{"star":false,"html":"<strong>Prolonged upright posture</strong> pools blood in leg veins → venous return, EDV and stroke volume decline."},{"star":false,"html":"<strong>Cardiac tamponade</strong> compresses the heart and prevents adequate filling → EDV and output decrease despite circulating blood."},{"star":false,"html":"<strong>Stiff ventricular muscle</strong> fills poorly for a given pressure → EDV and effective output may decline."},{"star":false,"html":"<strong>Very rapid heart rates</strong> shorten diastole → EDV falls, sometimes enough to lower output despite more beats."},{"star":true,"html":"<strong>Sympathetic β₁ stimulation</strong> raises intracellular cAMP/Ca²⁺ cycling → myocardial contractility and relaxation increase."},{"star":false,"html":"<strong>Vagal stimulation</strong> chiefly slows heart rate and has comparatively little direct influence on ventricular contractility."},{"star":false,"html":"<strong>Hypoxia and hypercapnia</strong> can depress myocardial contractility → stroke volume decreases at a given filling level."},{"star":false,"html":"<strong>Acidosis and certain antiarrhythmic drugs</strong> weaken inotropy → myocardial output can fall without an initial preload reduction."},{"star":false,"html":"<strong>Heart failure</strong> shifts the Starling relation downward → extra filling increasingly causes congestion rather than adequate output gains."},{"star":false,"html":"<strong>Exercise cardiac output</strong> rises because sympathetic activity increases rate/contractility while muscle and breathing pumps improve venous return."},{"star":false,"html":"<strong>Haemorrhage</strong> lowers venous return and preload → compensatory tachycardia may not prevent falling output."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Resting cardiac output</td>\n  <td>About 5–5.5 L/min</td>\n  <td>Approximate normal resting adult value.</td>\n</tr>\n<tr>\n  <td>Example cardiac output</td>\n  <td>75 beats/min × 70 mL = 5.25 L/min</td>\n  <td>Shows CO = HR × SV with units.</td>\n</tr>\n<tr>\n  <td>Faster-heart counterexample</td>\n  <td>130 beats/min × 35 mL = 4.55 L/min</td>\n  <td>Demonstrates reduced output despite tachycardia when SV falls.</td>\n</tr>\n<tr>\n  <td>Example cardiac index</td>\n  <td>5.25 L/min ÷ 1.75 m² = 3.0 L/min/m²</td>\n  <td>Adjusts output for body size.</td>\n</tr>\n<tr>\n  <td>Cardiac-output equation</td>\n  <td>CO = HR × SV</td>\n  <td>Heart rate and stroke volume jointly determine output.</td>\n</tr>\n<tr>\n  <td>Cardiac-index equation</td>\n  <td>CI = CO ÷ BSA</td>\n  <td>Adjusts cardiac output for body surface area.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Frank–Starling response</strong>: Venous return rises → EDV and sarcomere stretch increase → calcium sensitivity/filament overlap improve → greater contractile force → higher stroke volume.</li>\n<li><strong>Contractility shift</strong>: Sympathetic β₁ receptor activation → cAMP/PKA rises → more calcium is available and cleared rapidly → stroke volume increases at the same filling.</li>\n<li><strong>Tachycardia limitation</strong>: Heart rate rises excessively → diastole becomes short → ventricular filling and stroke volume fall → total cardiac output may decrease.</li>\n<li><strong>Haemorrhage</strong>: Blood volume falls → venous return and preload decrease → Frank–Starling output declines → tachycardia/vasoconstriction partly defend pressure but cannot restore lost volume.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Preload</strong></th>\n  <th><strong>Afterload</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Meaning</td>\n  <td>Stretch before ventricular contraction.</td>\n  <td>Pressure/load resisted during ejection.</td>\n</tr>\n<tr>\n  <td>Clinical estimate</td>\n  <td>EDV or filling pressure.</td>\n  <td>Arterial pressure or outflow resistance.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Along Starling curve</strong></th>\n  <th><strong>Different Starling curve</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Main change</td>\n  <td>Preload changed, contractility comparable.</td>\n  <td>Intrinsic contractility changed.</td>\n</tr>\n<tr>\n  <td>At equal EDV</td>\n  <td>Same intrinsic pumping capability.</td>\n  <td>Higher/lower ejection capability.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Doubling heart rate</strong> necessarily doubles output → Truth: Reduced filling can lower SV enough that output declines.</li>\n<li>Trap: <strong>Greater preload</strong> is identical to stronger intrinsic contractility → Truth: Preload moves along the Starling curve; contractility changes the curve itself.</li>\n<li>Trap: <strong>Increased afterload</strong> automatically raises stroke volume → Truth: Higher ejection resistance can increase ESV and reduce SV.</li>\n<li>Trap: <strong>Frank–Starling law</strong> operates mainly because faster nerves are activated → Truth: The fundamental mechanism is myocardial stretch-dependent force generation.</li>\n<li>Trap: <strong>Blood loss tachycardia</strong> fully restores cardiac output → Truth: Low venous return may keep preload and output low.</li>\n</ul>\n"},{"slug":"co-measurement","must":[{"star":true,"html":"<strong>Fick principle</strong> calculates blood flow from oxygen consumption divided by the arterial-to-mixed-venous oxygen content difference."},{"star":false,"html":"<strong>Oxygen consumption</strong> equals cardiac output times oxygen removed from each unit volume of blood as it crosses systemic tissues."},{"star":false,"html":"<strong>Arterial oxygen content</strong> describes actual oxygen carried per volume of blood, not merely the fraction of haemoglobin saturated."},{"star":false,"html":"<strong>Mixed venous oxygen content</strong> is measured in pulmonary arterial blood because it contains venous return mixed from the whole body."},{"star":false,"html":"<strong>Arterial sample</strong> may be taken from a systemic artery because systemic arterial oxygen content is approximately uniform."},{"star":false,"html":"<strong>Fick steady state</strong> is required because measured oxygen uptake and blood content differences must represent the same stable circulation."},{"star":false,"html":"<strong>Anaemia and oxygen saturation</strong> must be distinguished because normal saturation can coexist with low content when haemoglobin is reduced."},{"star":false,"html":"<strong>Higher arteriovenous oxygen difference</strong> at fixed oxygen consumption implies lower cardiac output because tissues extract more from each unit of blood."},{"star":false,"html":"<strong>Indicator dilution</strong> (supplementary) estimates flow by injecting a known marker and measuring its downstream concentration over time."},{"star":false,"html":"<strong>Rapid indicator flow</strong> produces a smaller/shorter concentration–time curve for the same known indicator dose."},{"star":false,"html":"<strong>Thermodilution</strong> uses cold saline as an indicator; temperature changes downstream are related to cardiac blood flow."},{"star":true,"html":"<strong>Stroke work</strong> is approximate stroke volume multiplied by ejection pressure → greater output or greater pressure requires more mechanical energy."},{"star":false,"html":"<strong>Pressure–volume loop area</strong> represents the external mechanical stroke work performed by a ventricle each beat."},{"star":false,"html":"<strong>Equal biventricular volumes</strong> do not imply equal work because left ventricle ejects against much higher arterial pressure."},{"star":false,"html":"<strong>Pressure loading</strong> raises ventricular wall stress and energy demand more than an equivalent simple volume increase."},{"star":false,"html":"<strong>Myocardial oxygen demand</strong> rises with wall tension, contractility and heart rate because all raise energetic work."},{"star":true,"html":"<strong>Coronary flow increase</strong> is needed during exercise because myocardium already extracts most available oxygen from resting coronary blood."},{"star":false,"html":"<strong>Pressure-driven oxygen demand</strong> explains why severe arterial hypertension or aortic stenosis increases left ventricular energy use."},{"star":false,"html":"<strong>Volume-driven workload</strong> increases with higher SV even if arterial pressure is comparatively unchanged."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Lecture Fick oxygen consumption</td>\n  <td>250 mL O₂/min</td>\n  <td>Amount of oxygen consumed per minute in example.</td>\n</tr>\n<tr>\n  <td>Arterial oxygen content in example</td>\n  <td>0.20 mL O₂/mL blood</td>\n  <td>Oxygen entering systemic tissues.</td>\n</tr>\n<tr>\n  <td>Mixed venous oxygen content in example</td>\n  <td>0.15 mL O₂/mL blood</td>\n  <td>Oxygen remaining after tissue extraction.</td>\n</tr>\n<tr>\n  <td>Computed cardiac output</td>\n  <td>250 ÷ (0.20 − 0.15) = 5000 mL/min</td>\n  <td>Equivalent to 5.0 L/min.</td>\n</tr>\n<tr>\n  <td>Example stroke work</td>\n  <td>70 mL × 100 mmHg = 7000 mmHg·mL</td>\n  <td>Approximate external work of one ventricular beat.</td>\n</tr>\n<tr>\n  <td>Example stroke work in joules</td>\n  <td>About 0.93 J</td>\n  <td>Equivalent conversion of the illustrated pressure–volume work.</td>\n</tr>\n<tr>\n  <td>Typical myocardial resting oxygen extraction</td>\n  <td>About 70%</td>\n  <td>Little additional extraction capacity is available during exercise.</td>\n</tr>\n<tr>\n  <td>Fick cardiac-output equation</td>\n  <td>CO = V̇O₂ ÷ (CaO₂ − CvO₂)</td>\n  <td>Divide oxygen consumption by the content difference.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Fick measurement</strong>: Measure whole-body oxygen uptake → sample arterial O₂ content and pulmonary arterial mixed venous content → calculate content difference → divide oxygen uptake by difference → obtain cardiac output.</li>\n<li><strong>Example Fick calculation</strong>: Oxygen use 250 mL/min → arterial content 0.20 and venous 0.15 mL/mL → difference 0.05 → CO = 250/0.05 → 5 L/min.</li>\n<li><strong>Stroke work and pressure</strong>: Ventricle fills to EDV → contracts against arterial pressure and ejects SV → pressure–volume loop encloses an area → area represents external stroke work.</li>\n<li><strong>Myocardial demand</strong>: Pressure, rate or contractility rises → myocardial work and oxygen consumption increase → local metabolites dilate coronaries → coronary blood flow must increase.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Oxygen content</strong></th>\n  <th><strong>Oxygen saturation</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Describes</td>\n  <td>Total O₂ carried per blood volume.</td>\n  <td>Percentage of available haemoglobin binding sites occupied.</td>\n</tr>\n<tr>\n  <td>Role in Fick calculation</td>\n  <td>Required measurement.</td>\n  <td>Insufficient alone without haemoglobin concentration.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Stroke volume</strong></th>\n  <th><strong>Stroke work</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Meaning</td>\n  <td>Blood volume ejected per beat.</td>\n  <td>Mechanical energy of ejecting that blood against pressure.</td>\n</tr>\n<tr>\n  <td>Governing variables</td>\n  <td>EDV and ESV.</td>\n  <td>Stroke volume and pressure.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Fick cardiac output</strong> can be calculated from pulse and oxygen saturation alone → Truth: Measured oxygen consumption and oxygen CONTENT difference are necessary.</li>\n<li>Trap: <strong>Mixed venous oxygen</strong> should be sampled from one peripheral arm vein → Truth: Pulmonary arterial blood represents mixed systemic venous return.</li>\n<li>Trap: <strong>High arterial saturation</strong> guarantees high arterial oxygen content → Truth: Anaemia reduces oxygen content despite high saturation.</li>\n<li>Trap: <strong>Left and right stroke work</strong> must match because their output matches → Truth: Left ventricle performs more pressure work for the same volume.</li>\n<li>Trap: <strong>Increased myocardial demand</strong> is met mainly through extracting much more oxygen → Truth: Extraction is already high and coronary blood flow must rise.</li>\n</ul>\n"},{"slug":"hemodynamics","must":[{"star":true,"html":"<strong>Blood flow</strong> is driven by pressure difference across a vascular segment and opposed by its resistance."},{"star":false,"html":"<strong>High absolute pressure</strong> does not guarantee flow because a pressure gradient, not a pressure value alone, drives movement."},{"star":false,"html":"<strong>Arterial elastic recoil</strong> releases stored systolic energy during diastole → blood continues moving while the heart relaxes."},{"star":false,"html":"<strong>Arterioles</strong> contain smooth muscle that adjusts radius → they provide the main controllable peripheral resistance."},{"star":false,"html":"<strong>Capillaries</strong> have very thin walls and enormous exchange area → diffusion, filtration and nutrient delivery occur efficiently."},{"star":false,"html":"<strong>Venules and veins</strong> are compliant low-pressure channels → they return and store large blood volumes."},{"star":false,"html":"<strong>Flow versus velocity</strong> distinguishes volume crossing a plane per time (Q) from blood displacement per time (v)."},{"star":true,"html":"<strong>Continuity relation</strong> states Q = v × A → at equal flow, greater total cross-sectional area means lower mean velocity."},{"star":false,"html":"<strong>Slow capillary velocity</strong> occurs because the combined cross-sectional area of parallel capillaries far exceeds that of the aorta."},{"star":false,"html":"<strong>Laminar blood flow</strong> forms ordered layers with highest velocity centrally and near-zero velocity at the vessel wall."},{"star":false,"html":"<strong>Laminar flow silence</strong> reflects smooth layered motion without significant vibration of vessel walls."},{"star":false,"html":"<strong>Turbulent flow</strong> mixes streams irregularly → vessel vibration can generate audible cardiac murmurs and vascular bruits."},{"star":false,"html":"<strong>Reynolds number</strong> estimates turbulence likelihood from fluid density, speed, vessel diameter and viscosity."},{"star":false,"html":"<strong>High velocity</strong> favours turbulence, especially through narrowed valves or a high-flow arteriovenous connection."},{"star":false,"html":"<strong>Lower viscosity</strong> can increase Reynolds number and promote flow murmurs in anaemia."},{"star":false,"html":"<strong>Larger vessel diameter</strong> increases turbulence tendency at similar velocity and viscosity."},{"star":true,"html":"<strong>Hagen–Poiseuille relation</strong> shows ideal tube flow rises with the fourth power of radius and pressure difference."},{"star":false,"html":"<strong>Hydraulic resistance</strong> increases with blood viscosity and vessel length but falls dramatically as radius increases."},{"star":false,"html":"<strong>Halved arteriolar radius</strong> increases theoretical resistance sixteenfold when other conditions stay fixed."},{"star":false,"html":"<strong>Arteriolar constriction</strong> raises resistance and lowers local flow for a given pressure gradient."},{"star":false,"html":"<strong>Parallel vascular pathways</strong> reduce total resistance because blood has several alternative routes."},{"star":false,"html":"<strong>Series vascular resistances</strong> add together because blood must cross each segment successively."},{"star":false,"html":"<strong>Polycythaemia</strong> raises haematocrit and viscosity → vascular resistance and myocardial work increase."},{"star":false,"html":"<strong>Anaemia</strong> lowers viscosity but reduces oxygen content → compensatory faster flow can still increase cardiac workload."},{"star":false,"html":"<strong>Doppler technique</strong> measures velocity; volume flow also requires cross-sectional area."},{"star":false,"html":"<strong>Electromagnetic flow measurement</strong> uses voltage generated as electrically conductive blood moves through a magnetic field."},{"star":true,"html":"<strong>Vascular compliance</strong> describes change in vessel volume per change in pressure → compliant veins store much blood with little pressure increase."},{"star":false,"html":"<strong>Venoconstriction</strong> squeezes the blood reservoir → central venous return and ventricular filling increase."},{"star":false,"html":"<strong>Capacitance vessels</strong> are mainly veins because their large compliance permits substantial storage at low pressures."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Radius halved (other factors constant)</td>\n  <td>Resistance ×16</td>\n  <td>Fourth-power radius sensitivity.</td>\n</tr>\n<tr>\n  <td>Radius narrowed by 20%</td>\n  <td>Flow falls by more than half</td>\n  <td>Poiseuille dependence: 0.8⁴ ≈ 0.41.</td>\n</tr>\n<tr>\n  <td>Blood held in the veins at rest</td>\n  <td>About two-thirds</td>\n  <td>High venous compliance supplies a reservoir.</td>\n</tr>\n<tr>\n  <td>Arm-to-tongue circulation time</td>\n  <td>About 15 seconds</td>\n  <td>Lecturer's example of whole-body transit assessment.</td>\n</tr>\n<tr>\n  <td>Example pressure–flow relation</td>\n  <td>80 mmHg ÷ 20 mmHg·min/L = 4 L/min</td>\n  <td>Flow requires a pressure difference and resistance.</td>\n</tr>\n<tr>\n  <td>Flow relation</td>\n  <td>Q = ΔP ÷ R</td>\n  <td>Pressure difference and resistance determine flow.</td>\n</tr>\n<tr>\n  <td>Hagen–Poiseuille ideal flow</td>\n  <td>Q = πΔPr⁴ ÷ 8ηL</td>\n  <td>Radius enters to the fourth power in ideal-tube flow.</td>\n</tr>\n<tr>\n  <td>Reynolds number</td>\n  <td>Re = ρvD ÷ η</td>\n  <td>Estimates the likelihood of turbulence.</td>\n</tr>\n<tr>\n  <td>Compliance relation</td>\n  <td>C = ΔV ÷ ΔP</td>\n  <td>Quantifies volume stored for a pressure change.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Pressure-driven flow</strong>: Upstream pressure exceeds downstream pressure → pressure gradient acts across vascular resistance → blood moves according to Q = ΔP/R.</li>\n<li><strong>Poiseuille effect</strong>: Arteriolar smooth muscle contracts → radius decreases → resistance rises roughly as 1/r⁴ → tissue flow falls sharply at fixed pressure difference.</li>\n<li><strong>Continuity</strong>: Aorta branches into many capillaries → total cross-sectional area rises greatly → mean blood velocity falls → exchange time and area increase.</li>\n<li><strong>Venous capacitance</strong>: Veins relax → large volume stored at low pressure → venous return can decline; sympathetic constriction shifts stored blood to heart → output improves.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Volume flow</strong></th>\n  <th><strong>Flow velocity</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Definition</td>\n  <td>Volume crossing a plane per unit time.</td>\n  <td>Distance travelled per unit time.</td>\n</tr>\n<tr>\n  <td>Link</td>\n  <td>Q = v × total area.</td>\n  <td>v = Q/total area.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Laminar flow</strong></th>\n  <th><strong>Turbulent flow</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Pattern</td>\n  <td>Smooth parallel layers.</td>\n  <td>Irregular mixing and eddies.</td>\n</tr>\n<tr>\n  <td>Sound</td>\n  <td>Usually silent.</td>\n  <td>May produce murmurs/bruits.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Resistance (R)</strong></th>\n  <th><strong>Reynolds number (Re)</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Represents</td>\n  <td>Opposition to flow.</td>\n  <td>Tendency towards turbulence.</td>\n</tr>\n<tr>\n  <td>Important determinants</td>\n  <td>Radius to the fourth power, length, viscosity.</td>\n  <td>Density, velocity, diameter, inverse viscosity.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Higher arterial pressure</strong> always guarantees greater local tissue flow → Truth: Flow depends on pressure DROP divided by resistance.</li>\n<li>Trap: <strong>Blood moves fastest in capillaries</strong> because they are individually narrow → Truth: Their enormous total area makes mean velocity slowest.</li>\n<li>Trap: <strong>Poiseuille equation</strong> makes resistance directly proportional to radius → Truth: Resistance varies inversely with the fourth power of radius.</li>\n<li>Trap: <strong>A lower haematocrit</strong> must lower cardiac work → Truth: Anaemia lowers viscosity but reduced oxygen content can drive high-output work.</li>\n<li>Trap: <strong>Resistance and Reynolds number</strong> measure the same property → Truth: One opposes flow; the other predicts tendency to turbulence.</li>\n<li>Trap: <strong>Veins</strong> carry little blood because they have low pressure → Truth: High compliance lets them store most circulating blood at low pressure.</li>\n</ul>\n"},{"slug":"blood-pressure","must":[{"star":true,"html":"<strong>Systolic arterial pressure</strong> is maximum arterial pressure reached during one cardiac cycle when ventricular ejection distends arteries."},{"star":false,"html":"<strong>Diastolic arterial pressure</strong> is minimum arterial pressure just before the next ejection, sustained partly by elastic recoil."},{"star":false,"html":"<strong>Windkessel effect</strong> stores energy when large elastic arteries stretch in systole and releases it through recoil during diastole."},{"star":false,"html":"<strong>Stiff aorta</strong> stretches less for a given stroke volume → systolic and pulse pressures rise."},{"star":true,"html":"<strong>Mean arterial pressure</strong> depends strongly on cardiac output and systemic vascular resistance, not on heart rate alone."},{"star":false,"html":"<strong>Normal arterial pressure</strong> does not prove normal organ perfusion because severe vasoconstriction may mask reduced cardiac output."},{"star":false,"html":"<strong>Pulse pressure</strong> is systolic minus diastolic pressure → it widens when stroke volume or arterial stiffness rises."},{"star":false,"html":"<strong>Higher stroke volume</strong> tends to raise systolic pressure and pulse pressure because more blood is ejected into elastic arteries."},{"star":false,"html":"<strong>Long diastolic duration</strong> makes mean arterial pressure closer to diastolic than systolic pressure at usual resting rates."},{"star":true,"html":"<strong>Approximate MAP</strong> equals DBP plus one-third of pulse pressure at normal resting heart rates."},{"star":false,"html":"<strong>Hydrostatic pressure</strong> adds below heart level and subtracts above → arm position can alter measured blood pressure."},{"star":false,"html":"<strong>Cuff at heart level</strong> avoids false elevation if the arm is too low or false reduction if too high."},{"star":false,"html":"<strong>Direct arterial cannulation</strong> measures intravascular pressure via a sensor, whereas routine cuffs estimate pressure indirectly."},{"star":false,"html":"<strong>Cuff occlusion</strong> stops brachial artery flow when cuff pressure exceeds systolic pressure → no Korotkoff sounds occur."},{"star":true,"html":"<strong>First Korotkoff sound</strong> occurs when cuff pressure falls just below systolic pressure and blood jets through the compressed artery."},{"star":false,"html":"<strong>Korotkoff sound disappearance</strong> during further deflation approximates diastolic pressure when flow becomes less turbulent."},{"star":false,"html":"<strong>Korotkoff sounds</strong> arise from turbulent vibration in a partly compressed brachial artery, not from heart valve closure."},{"star":false,"html":"<strong>Palpatory systolic estimation</strong> helps prevent missing the true systolic pressure when an auscultatory gap occurs."},{"star":false,"html":"<strong>Auscultatory gap</strong> is temporary silence between Korotkoff sounds → unrecognised gaps can lead to incorrect systolic assessment."},{"star":false,"html":"<strong>Appropriate cuff size</strong> is necessary because a cuff that is too narrow overestimates and one too large underestimates pressure."},{"star":false,"html":"<strong>Measurement preparation</strong> includes quiet seated rest with supported back and feet, limiting voluntary muscle and sympathetic artefacts."},{"star":false,"html":"<strong>Slow cuff deflation</strong> permits accurate identification of first and final Korotkoff sounds."},{"star":false,"html":"<strong>Arteriolar resistance</strong> consumes much of the systemic pressure drop because narrow muscular resistance vessels oppose flow strongly."},{"star":false,"html":"<strong>Arteriolar damping</strong> makes the arterial pulse progressively smaller before blood reaches capillaries."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Lecture illustrative blood pressure</td>\n  <td>120/70 mmHg</td>\n  <td>Used to calculate pulse pressure and MAP.</td>\n</tr>\n<tr>\n  <td>Example pulse pressure</td>\n  <td>50 mmHg</td>\n  <td>120 systolic minus 70 diastolic.</td>\n</tr>\n<tr>\n  <td>Estimated MAP in example</td>\n  <td>About 87 mmHg</td>\n  <td>70 + one-third of 50, not the simple midpoint.</td>\n</tr>\n<tr>\n  <td>Hydrostatic change per centimetre</td>\n  <td>About 0.77 mmHg/cm</td>\n  <td>Explains arm-height measurement errors.</td>\n</tr>\n<tr>\n  <td>Arm 20 cm below heart</td>\n  <td>Reading approximately 15–16 mmHg higher</td>\n  <td>Illustrates hydrostatic artefact.</td>\n</tr>\n<tr>\n  <td>Rest before cuff measurement</td>\n  <td>About 5 minutes</td>\n  <td>Reduces transient sympathetic and activity-related elevation.</td>\n</tr>\n<tr>\n  <td>Inflate after palpating systolic</td>\n  <td>About 20–30 mmHg above palpated value</td>\n  <td>Helps avoid missing a silent auscultatory interval.</td>\n</tr>\n<tr>\n  <td>Cuff deflation speed</td>\n  <td>About 2 mmHg/second</td>\n  <td>Enables accurate first/last sound identification.</td>\n</tr>\n<tr>\n  <td>Pulse-pressure equation</td>\n  <td>PP = SBP − DBP</td>\n  <td>Systolic minus diastolic pressure.</td>\n</tr>\n<tr>\n  <td>Approximate MAP at rest</td>\n  <td>MAP ≈ DBP + PP ÷ 3</td>\n  <td>Mean pressure is weighted towards diastole.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Windkessel pressure support</strong>: Left ventricle ejects → elastic aorta stretches and stores energy → ventricle relaxes → aortic recoil sustains pressure and blood flow during diastole.</li>\n<li><strong>Pressure cuff measurement</strong>: Inflate above systolic to stop flow → gradually deflate → first Korotkoff sound marks systolic → sounds change → disappearance marks diastolic.</li>\n<li><strong>Mean arterial pressure</strong>: Measure systolic and diastolic → calculate PP = SBP − DBP → estimate MAP = DBP + PP/3 → recognise longer resting diastole pulls mean towards DBP.</li>\n<li><strong>Height error</strong>: Arm lowered below heart → hydrostatic pressure increases at cuff → falsely high reading; arm lifted above heart → falsely low reading.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Systolic BP</strong></th>\n  <th><strong>Diastolic BP</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Timing</td>\n  <td>Peak during ejection.</td>\n  <td>Lowest just before next ejection.</td>\n</tr>\n<tr>\n  <td>Korotkoff marker</td>\n  <td>First tapping sound.</td>\n  <td>Disappearance of sound.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Pulse pressure</strong></th>\n  <th><strong>Mean arterial pressure</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Relation</td>\n  <td>SBP − DBP.</td>\n  <td>Approximate DBP + one-third PP.</td>\n</tr>\n<tr>\n  <td>Meaning</td>\n  <td>Size of arterial pressure swing.</td>\n  <td>Time-weighted pressure driving tissue blood flow.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>MAP</strong> is simply the arithmetic midpoint of systolic and diastolic values → Truth: Longer diastole makes MAP closer to DBP at rest.</li>\n<li>Trap: <strong>Korotkoff sounds</strong> are transmitted S1 and S2 valve sounds → Truth: They originate from flow through the partly compressed brachial artery.</li>\n<li>Trap: <strong>First Korotkoff sound</strong> gives diastolic pressure → Truth: It marks systolic; sound disappearance gives diastolic.</li>\n<li>Trap: <strong>Cuff below heart</strong> reads artificially low → Truth: Added hydrostatic pressure makes the value falsely high.</li>\n<li>Trap: <strong>Smaller-than-required cuff</strong> reads artificially low → Truth: Excess pressure may be needed to occlude artery, overestimating BP.</li>\n<li>Trap: <strong>Near-normal BP</strong> ensures adequate organ perfusion after blood loss → Truth: High resistance may preserve pressure despite low output.</li>\n</ul>\n"},{"slug":"pulses","must":[{"star":true,"html":"<strong>Arterial pulse</strong> is a pressure wave produced by ventricular ejection and travels faster than blood particles themselves."},{"star":false,"html":"<strong>Pulse-wave speed</strong> increases when arteries become stiffer, often with age or more distal arterial branching."},{"star":false,"html":"<strong>Pulse rate</strong> estimates the number of palpable arterial pressure waves each minute, which may differ from ventricular electrical activity."},{"star":false,"html":"<strong>Pulse rhythm</strong> describes the spacing between pressure waves and helps identify irregular heartbeats."},{"star":false,"html":"<strong>Pulse volume and strength</strong> reflect the amplitude and force of the peripheral pressure wave."},{"star":false,"html":"<strong>Pulse character</strong> describes the rise and fall of the pressure wave, which may alter in valve and vascular disease."},{"star":false,"html":"<strong>Pulse deficit</strong> occurs when some ventricular beats eject too little blood to generate a detectable peripheral pulse."},{"star":true,"html":"<strong>Jugular venous pulse (JVP)</strong> reflects right atrial pressure changes because internal jugular veins communicate without an intervening valve."},{"star":false,"html":"<strong>Visible JVP movement</strong> is normally non-palpable because venous pressures are too low to generate a firm arterial thrust."},{"star":false,"html":"<strong>Jugular a wave</strong> arises from right atrial contraction → venous pressure rises briefly near end-diastole."},{"star":false,"html":"<strong>Jugular c wave</strong> arises as the closed tricuspid valve bulges towards right atrium during early ventricular systole."},{"star":false,"html":"<strong>Jugular x descent</strong> follows atrial relaxation and downward movement of tricuspid annulus during ventricular contraction."},{"star":false,"html":"<strong>Jugular v wave</strong> grows as right atrium fills from veins while the tricuspid valve remains closed."},{"star":false,"html":"<strong>Jugular y descent</strong> follows tricuspid opening → right atrium empties rapidly into right ventricle."},{"star":false,"html":"<strong>Jugular waveform timing</strong> distinguishes atrial contraction, valve bulging, atrial filling and atrial emptying."},{"star":false,"html":"<strong>Carotid pulse</strong> is palpable and generally has one dominant thrust per beat, unlike the soft, multiwave jugular venous movement."},{"star":false,"html":"<strong>Jugular respiratory change</strong> normally makes venous pressure fall during inspiration because thoracic pressure decreases and return improves."},{"star":false,"html":"<strong>Jugular postural change</strong> occurs because venous column height depends on body position and right atrial pressure."},{"star":true,"html":"<strong>JVP bedside assessment</strong> measures the vertical venous pulsation above the sternal angle with the patient partially reclined."},{"star":false,"html":"<strong>Elevated jugular venous pressure</strong> indicates increased right atrial filling pressure, as may occur in right-sided heart failure."},{"star":true,"html":"<strong>Giant systolic v (cv) wave</strong> suggests tricuspid regurgitation because ventricular contraction drives blood back into right atrium and veins."},{"star":false,"html":"<strong>Cannon a wave</strong> occurs when right atrium contracts against a closed tricuspid valve, especially in AV dissociation or complete heart block."},{"star":false,"html":"<strong>Giant a and giant v waves</strong> differ in timing: atrial contraction versus systolic ventricular regurgitation."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Approximate aortic pulse-wave velocity</td>\n  <td>About 3–5 m/s</td>\n  <td>Pulse wave travels much faster than blood flow.</td>\n</tr>\n<tr>\n  <td>Pulse-wave velocity in larger peripheral branches</td>\n  <td>About 7–10 m/s</td>\n  <td>More rigid peripheral arteries transmit waves faster.</td>\n</tr>\n<tr>\n  <td>Typical JVP patient incline</td>\n  <td>About 45° (adjust as needed)</td>\n  <td>Makes the visible venous column measurable.</td>\n</tr>\n<tr>\n  <td>Approximate normal JVP above sternal angle</td>\n  <td>No more than about 3–4 cm</td>\n  <td>Higher levels suggest raised right atrial pressure.</td>\n</tr>\n<tr>\n  <td>Sternal-angle distance above right atrium</td>\n  <td>About 5 cm</td>\n  <td>Fixed reference for pressure-height estimates.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Arterial pulse production</strong>: Left ventricular ejection distends the aorta → wall pressure disturbance travels along arteries → peripheral pulse appears before the ejected blood physically reaches the site.</li>\n<li><strong>Normal JVP waveform</strong>: Atrial systole raises a wave → ventricular contraction bulges tricuspid valve (c) and draws annulus down (x) → atrium fills behind closed valve (v) → tricuspid opens (y).</li>\n<li><strong>Tricuspid regurgitation</strong>: Right ventricle contracts → blood leaks backward through tricuspid valve → right atrial pressure rises in systole → a large JVP v/cv wave appears.</li>\n<li><strong>Complete heart block</strong>: Atria and ventricles contract independently → an atrium sometimes contracts against shut tricuspid valve → extreme atrial pressure → cannon a wave.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Jugular venous pulse</strong></th>\n  <th><strong>Carotid arterial pulse</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Palpability</td>\n  <td>Usually visible but not palpable.</td>\n  <td>Firm palpable single pulse.</td>\n</tr>\n<tr>\n  <td>Wave shape</td>\n  <td>Multiple undulations each cycle.</td>\n  <td>One dominant systolic thrust.</td>\n</tr>\n<tr>\n  <td>Response to posture/inspiration</td>\n  <td>Changes markedly.</td>\n  <td>Changes little.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Cannon a wave</strong></th>\n  <th><strong>Giant v (cv) wave</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Cause</td>\n  <td>Atrium contracts against closed tricuspid valve.</td>\n  <td>Ventricle regurgitates into right atrium.</td>\n</tr>\n<tr>\n  <td>Typical disease</td>\n  <td>Complete AV block/AV dissociation.</td>\n  <td>Tricuspid regurgitation.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Pulse speed</strong> measures blood-cell velocity through an artery → Truth: A pressure wave travels ahead of bulk blood movement.</li>\n<li>Trap: <strong>JVP</strong> represents left atrial pressure → Truth: Internal jugular veins transmit right atrial pressure changes.</li>\n<li>Trap: <strong>Atrial v wave</strong> is produced by atrial contraction → Truth: It forms during atrial venous filling with tricuspid closed.</li>\n<li>Trap: <strong>Large tricuspid regurgitation wave</strong> is always a cannon a wave → Truth: Systolic regurgitation causes giant v/cv waves.</li>\n<li>Trap: <strong>Jugular pulsation</strong> can be felt as a strong single pulse → Truth: Palpable single thrust is characteristic of carotid arterial pulse.</li>\n<li>Trap: <strong>Patient inclination</strong> has no influence on measured JVP → Truth: Position alters visible venous height; assess vertical distance above sternal angle.</li>\n</ul>\n"},{"slug":"venous-return","must":[{"star":true,"html":"<strong>Venous return</strong> is blood reaching right atrium per minute and equals cardiac output in a steady circulation."},{"star":false,"html":"<strong>Adequate ventricular filling</strong> requires sufficient venous return because even a strong heart cannot pump blood it has not received."},{"star":true,"html":"<strong>Venous capacitance</strong> reflects high vessel compliance → systemic veins store much of circulating blood at low pressure."},{"star":false,"html":"<strong>Vascular compliance</strong> equals change in volume divided by change in pressure; greater compliance permits larger filling without marked pressure rise."},{"star":false,"html":"<strong>Venoconstriction</strong> reduces venous storage capacity → stored blood moves towards heart and ventricular preload increases."},{"star":false,"html":"<strong>Venodilatation</strong> increases peripheral blood storage → central filling and cardiac output may fall if compensation fails."},{"star":true,"html":"<strong>Venous-return driving gradient</strong> is mean systemic filling pressure minus right atrial pressure, divided by resistance to venous return."},{"star":false,"html":"<strong>Mean systemic filling pressure (Pmsf)</strong> reflects circulatory fullness and stressed vascular volume; higher fullness usually raises venous return."},{"star":false,"html":"<strong>Higher right atrial pressure</strong> opposes the return gradient → flow back to the right heart decreases when other factors are fixed."},{"star":false,"html":"<strong>Resistance to venous return</strong> limits blood movement from peripheral circulation towards the right atrium."},{"star":false,"html":"<strong>Skeletal-muscle pump</strong> compresses deep veins during leg movement → blood is pushed heartward through one-way valves."},{"star":false,"html":"<strong>Venous valves</strong> prevent backward movement when limb muscles relax → blood accumulates less in distal legs during walking."},{"star":false,"html":"<strong>Motionless standing</strong> disables rhythmic calf compression → blood pools in compliant leg veins and venous return falls."},{"star":false,"html":"<strong>Inspiration</strong> lowers intrathoracic pressure and increases abdominal pressure → systemic venous blood is drawn towards the thorax."},{"star":false,"html":"<strong>Arterial pulsation</strong> compresses some neighbouring veins → assists intermittent venous return."},{"star":true,"html":"<strong>Central venous pressure (CVP)</strong> approximately reflects right atrial pressure → raised values may indicate excess volume or impaired right-heart emptying."},{"star":false,"html":"<strong>Jugular venous pressure</strong> provides a clinical estimate of right atrial pressure because neck veins communicate with the atrium."},{"star":false,"html":"<strong>Head and neck veins</strong> can collapse when upright because venous pressure above heart level becomes subatmospheric."},{"star":false,"html":"<strong>Dural venous sinuses</strong> remain patent despite low pressure because rigid meningeal attachments prevent collapse."},{"star":false,"html":"<strong>Open venous sinus above heart</strong> creates an air-embolism risk because subatmospheric venous pressure can draw air in."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Usual central venous pressure</td>\n  <td>A few mmHg</td>\n  <td>Represents low right atrial filling pressure in normal circumstances.</td>\n</tr>\n<tr>\n  <td>Lecture illustrative CVP</td>\n  <td>About 4.6 mmHg</td>\n  <td>Demonstrates low central venous pressure.</td>\n</tr>\n<tr>\n  <td>Venous blood reservoir</td>\n  <td>About half or more of systemic blood at rest</td>\n  <td>High venous compliance influences preload and shock compensation.</td>\n</tr>\n<tr>\n  <td>Venous-return relation</td>\n  <td>VR = (Pmsf − PRA) ÷ RVR</td>\n  <td>Upstream mean filling pressure must exceed right atrial pressure.</td>\n</tr>\n<tr>\n  <td>Venous compliance</td>\n  <td>C = ΔV ÷ ΔP</td>\n  <td>Large compliance supports venous storage.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Venous-return pressure relationship</strong>: Blood volume/venous tone raises Pmsf → gradient to right atrium increases → venous return rises; rising right atrial pressure reduces that gradient and return.</li>\n<li><strong>Skeletal-muscle pump</strong>: Calf muscles contract → deep veins are compressed → upstream one-way valves open and downstream valves close → blood moves towards heart.</li>\n<li><strong>Respiratory pump</strong>: Inspiration lowers thoracic pressure and raises abdominal pressure → pressure gradient towards chest increases → systemic venous return to right atrium rises.</li>\n<li><strong>Postural pooling</strong>: Person stands motionless → gravity distends leg veins → central venous return and EDV decrease → stroke volume falls → dizziness may occur.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Venous compliance</strong></th>\n  <th><strong>Venous-return resistance</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Meaning</td>\n  <td>Volume stored per change in pressure.</td>\n  <td>Opposition to blood returning to heart.</td>\n</tr>\n<tr>\n  <td>Consequence of increase</td>\n  <td>More blood held at low pressure.</td>\n  <td>Less return for a given driving gradient.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Mean systemic filling pressure</strong></th>\n  <th><strong>Right atrial pressure</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Position in venous-return equation</td>\n  <td>Upstream driving pressure.</td>\n  <td>Downstream backpressure.</td>\n</tr>\n<tr>\n  <td>Effect of increase at fixed other value</td>\n  <td>Tends to raise VR.</td>\n  <td>Tends to reduce VR.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Venous return</strong> must be lower than cardiac output in a healthy steady state → Truth: Equal long-term inflow and outflow are required.</li>\n<li>Trap: <strong>Veins</strong> hold little blood because their pressure is low → Truth: High compliance allows large volumes at low pressure.</li>\n<li>Trap: <strong>Increased right atrial pressure</strong> increases return because the heart is fuller → Truth: It opposes the venous-return driving gradient.</li>\n<li>Trap: <strong>Muscle pumping</strong> works without valves → Truth: One-way valves prevent each contraction from pushing blood backwards.</li>\n<li>Trap: <strong>All cranial venous channels</strong> collapse when standing → Truth: Dural sinuses stay open, creating air-embolism risk if breached.</li>\n</ul>\n"},{"slug":"microcirculation","must":[{"star":true,"html":"<strong>Microcirculation</strong> brings oxygen/nutrients near tissues and removes wastes through thin capillary walls and large total surface area."},{"star":false,"html":"<strong>Capillary wall</strong> is a single layer of endothelial cells on basement membrane, without contractile smooth muscle."},{"star":false,"html":"<strong>Continuous capillaries</strong> have relatively tight endothelium and are especially restrictive in the brain."},{"star":false,"html":"<strong>Fenestrated capillaries</strong> have endothelial pores → exchange is rapid in gut, glands and kidney."},{"star":false,"html":"<strong>Sinusoidal capillaries</strong> have wide discontinuities → large molecules and cells can pass more readily in liver, spleen and marrow."},{"star":true,"html":"<strong>Diffusion</strong> transports gases and small solutes down concentration gradients → it is the dominant mode of nutrient and gas exchange."},{"star":false,"html":"<strong>Filtration</strong> moves bulk fluid across capillary walls under hydrostatic and oncotic forces rather than a simple solute concentration gradient."},{"star":false,"html":"<strong>Arterioles and precapillary sphincters</strong> regulate microvascular inflow by changing resistance and opening or restricting individual capillary pathways."},{"star":false,"html":"<strong>Metabolic activity</strong> generates local vasodilators → more precapillary routes open and active tissue receives greater flow."},{"star":true,"html":"<strong>Capillary hydrostatic pressure (Pc)</strong> pushes water outward from the vascular lumen into the interstitium."},{"star":false,"html":"<strong>Plasma oncotic pressure (πc)</strong> from albumin retains water in blood by drawing fluid inward across a selective barrier."},{"star":false,"html":"<strong>Interstitial hydrostatic pressure (Pi)</strong> and interstitial protein pressure (πi) modify the net direction and magnitude of filtration."},{"star":false,"html":"<strong>Arteriolar dilatation</strong> raises downstream capillary hydrostatic pressure → outward filtration tends to increase."},{"star":false,"html":"<strong>Venous congestion</strong> raises capillary hydrostatic pressure → fluid accumulates in surrounding tissues if drainage is insufficient."},{"star":false,"html":"<strong>Hypoalbuminaemia</strong> lowers inward plasma oncotic pressure → outward capillary filtration becomes more likely."},{"star":false,"html":"<strong>Inflammatory mediators</strong> such as histamine increase permeability → proteins escape and contribute to tissue oedema."},{"star":false,"html":"<strong>Traditional Starling model</strong> describes filtration at arteriolar ends with substantial reabsorption towards venous ends of capillaries."},{"star":true,"html":"<strong>Endothelial glycocalyx</strong> forms the effective molecular barrier in the revised Starling model → sustained venous-end reabsorption is often small."},{"star":false,"html":"<strong>Revised Starling interpretation</strong> emphasises lymphatic drainage for return of most filtered fluid rather than routine venous reabsorption."},{"star":false,"html":"<strong>Low capillary velocity</strong> results from enormous combined capillary cross-sectional area → exchange can occur efficiently."},{"star":false,"html":"<strong>Capillary blood fraction</strong> is small despite very large aggregate capillary surface area → exchange efficiency does not require large blood storage."},{"star":false,"html":"<strong>Protein escape</strong> occurs through leaky capillaries → interstitial oncotic pressure rises and fluid accumulation increases."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Fraction of circulating blood in capillaries</td>\n  <td>About 5%</td>\n  <td>Huge exchange surface does not imply large blood reservoir.</td>\n</tr>\n<tr>\n  <td>Capillary hydrostatic pressure, arterial end</td>\n  <td>About 30 mmHg</td>\n  <td>Favourable to outward filtration.</td>\n</tr>\n<tr>\n  <td>Capillary hydrostatic pressure, venous end</td>\n  <td>About 10 mmHg</td>\n  <td>Traditional model predicts reduced outward filtration.</td>\n</tr>\n<tr>\n  <td>Plasma oncotic pressure in chapter model</td>\n  <td>About 28 mmHg</td>\n  <td>Albumin-rich plasma pulls fluid in.</td>\n</tr>\n<tr>\n  <td>Approximate tissue hydrostatic pressure</td>\n  <td>About −3 mmHg</td>\n  <td>Influences fluid movement from capillary to tissue.</td>\n</tr>\n<tr>\n  <td>Approximate tissue oncotic pressure</td>\n  <td>About 8 mmHg</td>\n  <td>Interstitial proteins tend to pull fluid outward.</td>\n</tr>\n<tr>\n  <td>Classic lecture filtration volume</td>\n  <td>About 24 L/day</td>\n  <td>Value belongs to the traditional Starling model.</td>\n</tr>\n<tr>\n  <td>Traditional model reabsorbed portion</td>\n  <td>About 85%</td>\n  <td>Classroom model, not the revised glycocalyx interpretation.</td>\n</tr>\n<tr>\n  <td>Traditional model lymphatic return portion</td>\n  <td>About 15%</td>\n  <td>Revised model instead emphasises lymph return of most filtered fluid.</td>\n</tr>\n<tr>\n  <td>Traditional Starling filtration model</td>\n  <td>Jv = Kf[(Pc − Pi) − σ(πc − πi)]</td>\n  <td>Lecture model; revised glycocalyx model changes reabsorption interpretation.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Diffusive exchange</strong>: Blood delivers oxygen/glucose close to cells → concentration gradient across thin capillary wall drives diffusion → tissues receive nutrients and blood picks up wastes.</li>\n<li><strong>Raised capillary pressure</strong>: Venous pressure rises → capillary hydrostatic pressure increases → outward water filtration exceeds lymphatic capacity → tissue oedema develops.</li>\n<li><strong>Inflammatory permeability</strong>: Histamine increases endothelial leak → protein moves into interstitium → tissue oncotic pull rises → additional water accumulates.</li>\n<li><strong>Glycocalyx and lymph</strong>: Filtered fluid passes endothelial surface layer → little sustained venous reabsorption occurs → lymphatics return most filtered fluid and escaped proteins to blood.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Diffusion</strong></th>\n  <th><strong>Filtration</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Main driving force</td>\n  <td>Solute concentration difference.</td>\n  <td>Hydrostatic/oncotic pressure balance.</td>\n</tr>\n<tr>\n  <td>Principal material moved</td>\n  <td>Gases and dissolved nutrients/wastes.</td>\n  <td>Bulk water and dissolved solutes.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Traditional Starling view</strong></th>\n  <th><strong>Revised glycocalyx view</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Venous-end fluid</td>\n  <td>Substantial reabsorption taught.</td>\n  <td>Little sustained reabsorption in most continuous capillaries.</td>\n</tr>\n<tr>\n  <td>Lymph contribution</td>\n  <td>Small residual share.</td>\n  <td>Main route returning filtered fluid and escaped protein.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Capillaries</strong> actively constrict with their own thick smooth muscle → Truth: Capillary walls are endothelial; upstream arterioles/sphincters regulate inflow.</li>\n<li>Trap: <strong>High albumin</strong> mainly pushes fluid out of capillaries → Truth: Plasma oncotic pressure pulls fluid into vascular space.</li>\n<li>Trap: <strong>Reduced capillary velocity</strong> means capillary blood flow volume is necessarily low → Truth: Total cross-sectional area is huge, so flow can remain substantial.</li>\n<li>Trap: <strong>Traditional venous reabsorption percentages</strong> describe current revised physiology → Truth: Glycocalyx-based model gives lymphatics the main steady-state return role.</li>\n<li>Trap: <strong>Inflammatory oedema</strong> requires high capillary pressure alone → Truth: Increased permeability and escaped protein can cause oedema even without major pressure rise.</li>\n</ul>\n"},{"slug":"edema","must":[{"star":true,"html":"<strong>Oedema</strong> is excess interstitial fluid when filtration and leak exceed the capacity of lymphatics to remove fluid."},{"star":false,"html":"<strong>Excess filtration</strong> can follow stronger outward hydrostatic forces, weaker plasma oncotic forces or increased wall permeability."},{"star":false,"html":"<strong>Insufficient lymph drainage</strong> produces swelling even when initial capillary filtration is near normal."},{"star":true,"html":"<strong>Increased venous pressure</strong> raises capillary hydrostatic pressure → more fluid is forced into tissue."},{"star":false,"html":"<strong>Prolonged standing</strong> increases leg venous and capillary pressures → dependent ankle oedema may form."},{"star":false,"html":"<strong>Venous obstruction</strong> prevents effective downstream drainage → pressure rises behind the block and local oedema develops."},{"star":false,"html":"<strong>Venous valve failure</strong> can cause chronic dependent congestion because blood reflux increases leg venous pressure."},{"star":false,"html":"<strong>Right-sided heart failure</strong> elevates systemic venous pressure → ankles, liver and abdominal fluid compartments become congested."},{"star":false,"html":"<strong>Left-sided heart failure</strong> raises pulmonary venous pressure → lung capillary filtration increases and pulmonary oedema develops."},{"star":true,"html":"<strong>Low albumin</strong> reduces plasma oncotic retention of water → filtration rises and widespread oedema can develop."},{"star":false,"html":"<strong>Cirrhosis</strong> reduces hepatic albumin production and can raise portal pressure → systemic/abdominal oedema becomes more likely."},{"star":false,"html":"<strong>Nephrotic syndrome</strong> loses plasma protein into urine → plasma oncotic pressure falls and peripheral swelling develops."},{"star":false,"html":"<strong>Protein malnutrition</strong> reduces albumin availability → interstitial water accumulates because vascular oncotic pull weakens."},{"star":false,"html":"<strong>Inflammatory histamine</strong> increases capillary permeability → fluid and protein leave blood into interstitium."},{"star":false,"html":"<strong>Bradykinin and substance P</strong> increase microvascular leak → tissue proteins attract more water and worsen swelling."},{"star":false,"html":"<strong>Lymphatic obstruction</strong> prevents return of fluid and protein → protein-rich swelling becomes chronic and can cause fibrosis."},{"star":false,"html":"<strong>Filariasis</strong> damages or obstructs lymphatics → lymphoedema may become severe and persistent."},{"star":false,"html":"<strong>Lymph-node removal</strong> after surgery may interrupt drainage → swelling develops downstream from the removed vessels."},{"star":false,"html":"<strong>General fluid retention</strong> increases circulating volume and vascular pressure → capillary filtration and oedema may rise."},{"star":false,"html":"<strong>Pitting oedema</strong> leaves an indentation after pressure because mobile interstitial fluid is displaced."},{"star":true,"html":"<strong>Chronic non-pitting lymphoedema</strong> develops when protein-rich fluid induces fibrosis and tissue thickening that cannot be indented easily."},{"star":false,"html":"<strong>Swelling distribution</strong> helps identify mechanism: dependent legs indicate systemic/venous causes, while one limb suggests local obstruction."},{"star":false,"html":"<strong>Pulmonary oedema</strong> creates breathlessness because alveolar/interstitial fluid impairs oxygen diffusion."},{"star":false,"html":"<strong>Ascites</strong> is peritoneal cavity fluid, often from portal/hepatic venous hypertension plus protein/fluid regulation abnormalities."},{"star":false,"html":"<strong>Starling forces</strong> consist of vascular/tissue hydrostatic and oncotic pressures, with permeability determining effective net filtration."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Named primary mechanisms of oedema in approved chapter</td>\n  <td>5 routes</td>\n  <td>Increased pressure, low albumin, high permeability, lymph block or overall fluid excess.</td>\n</tr>\n<tr>\n  <td>Traditional Starling filtration equation</td>\n  <td>Jv = Kf[(Pc − Pi) − σ(πc − πi)]</td>\n  <td>Force balance; glycocalyx and lymph must also be considered.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Venous oedema</strong>: Venous outflow obstruction or right failure → venous/capillary pressure rises → net fluid filtration increases → lymphatic capacity is exceeded → interstitial swelling develops.</li>\n<li><strong>Hypoalbuminaemic oedema</strong>: Liver synthesis fails or kidney loses albumin → plasma oncotic pressure falls → vascular water retention decreases → diffuse swelling develops.</li>\n<li><strong>Inflammatory oedema</strong>: Histamine/bradykinin/substance P increase wall permeability → fluid and proteins escape → tissue oncotic pull rises → oedema increases.</li>\n<li><strong>Lymphoedema</strong>: Lymph vessels are blocked or destroyed → filtered protein-rich fluid cannot return → inflammation/fibrosis builds → chronic firm, often non-pitting swelling develops.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Raised-hydrostatic-pressure oedema</strong></th>\n  <th><strong>Low-oncotic-pressure oedema</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Primary abnormality</td>\n  <td>Excess outward capillary push.</td>\n  <td>Inadequate plasma protein pull.</td>\n</tr>\n<tr>\n  <td>Examples</td>\n  <td>Venous blockage, heart failure.</td>\n  <td>Cirrhosis, nephrotic syndrome, malnutrition.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Pitting oedema</strong></th>\n  <th><strong>Non-pitting lymphoedema</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Texture</td>\n  <td>Fluid can be displaced by pressing.</td>\n  <td>Firm protein-rich, fibrotic tissue resists indentation.</td>\n</tr>\n<tr>\n  <td>Typical evolution</td>\n  <td>Often earlier/mobile fluid.</td>\n  <td>Often chronic lymphatic obstruction.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Every oedema</strong> is due to too much total blood volume → Truth: Local venous pressure, hypoalbuminaemia, inflammation and lymph blockage also cause swelling.</li>\n<li>Trap: <strong>Left-sided failure</strong> first causes ankle oedema → Truth: Pulmonary venous congestion and lung oedema are its characteristic backward effects.</li>\n<li>Trap: <strong>Low plasma albumin</strong> increases inward oncotic pull → Truth: Less albumin weakens water retention in blood.</li>\n<li>Trap: <strong>Lymph blockage</strong> only affects fluid, not proteins → Truth: Escaped proteins accumulate and promote fibrosis.</li>\n<li>Trap: <strong>Non-pitting oedema</strong> is necessarily an acute fluid leak → Truth: Chronic protein-rich lymphoedema can become fibrotic and firm.</li>\n</ul>\n"},{"slug":"lymphatics","must":[{"star":true,"html":"<strong>Lymphatic vessels</strong> return filtered interstitial fluid and escaped plasma proteins to the bloodstream, maintaining normal tissue fluid balance."},{"star":false,"html":"<strong>Blind-ended lymphatic capillaries</strong> open within tissue spaces → excess interstitial fluid can enter without requiring a separate arterial supply."},{"star":false,"html":"<strong>Overlapping endothelial flaps</strong> act as one-way entry valves → raised tissue pressure opens them, while higher lymph pressure closes them."},{"star":false,"html":"<strong>Lymphatic valves</strong> prevent backward flow as lymph moves through low-pressure collecting vessels."},{"star":true,"html":"<strong>Intrinsic lymph-vessel contraction</strong> generates forward flow without a central lymphatic pump equivalent to the heart."},{"star":false,"html":"<strong>Skeletal-muscle movements</strong> squeeze lymph vessels → valves direct lymph proximally, increasing drainage during activity."},{"star":false,"html":"<strong>Breathing movements</strong> vary thoracic and abdominal pressures → promote movement of lymph towards the venous circulation."},{"star":false,"html":"<strong>Adjacent arterial pulsation</strong> can mechanically compress lymph vessels and help propel their contents."},{"star":false,"html":"<strong>Lymph nodes</strong> filter lymph and expose carried material to immune cells → they support immune surveillance rather than pumping lymph."},{"star":true,"html":"<strong>Thoracic duct</strong> drains most of the body into the left venous angle where internal jugular and subclavian veins meet."},{"star":false,"html":"<strong>Right lymphatic duct</strong> drains the right upper body into the right venous angle."},{"star":false,"html":"<strong>Thoracic duct territory</strong> includes both lower limbs, abdomen and left upper body, not merely the chest."},{"star":false,"html":"<strong>Right lymphatic drainage</strong> includes right head/neck, right upper limb and right thoracic region."},{"star":false,"html":"<strong>Intestinal lacteals</strong> absorb chylomicrons carrying long-chain dietary fats → fat reaches blood through lymphatic circulation."},{"star":false,"html":"<strong>Chyle</strong> is milky intestinal lymph because absorbed chylomicrons are rich in triglyceride."},{"star":false,"html":"<strong>Short- and medium-chain fatty acids</strong> enter portal blood more directly rather than depending on intestinal chylomicron lymph transport."},{"star":true,"html":"<strong>Lymphatic reserve</strong> increases drainage when capillary filtration rises → swelling is delayed until filtration exceeds maximum return capacity."},{"star":false,"html":"<strong>Escaped plasma protein</strong> normally returns through lymphatics → lymph blockage increases interstitial oncotic pull and fluid retention."},{"star":false,"html":"<strong>Filariasis</strong> obstructs or injures lymph vessels → persistent protein-rich lymphoedema develops."},{"star":false,"html":"<strong>Lymph-node excision</strong> in cancer surgery may damage drainage pathways → swelling can occur in the limb they served."},{"star":false,"html":"<strong>Tumour-related lymphatic blockage</strong> prevents normal drainage → distal tissue swelling develops."},{"star":false,"html":"<strong>Chronic lymphoedema</strong> becomes firm and non-pitting as protein accumulation drives inflammation and fibrosis."},{"star":false,"html":"<strong>Immune consequences of lymphatic loss</strong> arise because antigen transport and lymph-node filtering become less effective."},{"star":false,"html":"<strong>Fat-malabsorption consequences</strong> arise when intestinal lymph drainage fails because long-chain fat transport is impaired."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Thoracic-duct drainage territory</td>\n  <td>Roughly three-quarters of body</td>\n  <td>Returns lymph to left venous angle.</td>\n</tr>\n<tr>\n  <td>Right lymphatic-duct territory</td>\n  <td>Right upper quarter of body</td>\n  <td>Returns lymph to right venous angle.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Lymph entry and return</strong>: Plasma filters into tissues → interstitial pressure opens overlapping lymphatic endothelial flaps → fluid/proteins enter lymph capillaries → valved collecting vessels move lymph → venous angles return it to blood.</li>\n<li><strong>Lymph propulsion</strong>: Intrinsic collecting-vessel contractions plus muscle movement/respiration/arterial pulsation compress lymph → one-way valves prevent reflux → fluid advances without a central lymphatic heart.</li>\n<li><strong>Fat absorption</strong>: Long-chain dietary fat is packaged into chylomicrons → enters intestinal lacteals → travels as chyle through lymphatic channels/thoracic duct → enters venous blood.</li>\n<li><strong>Lymphatic obstruction</strong>: Parasites, cancer or surgery damage lymph drainage → fluid and proteins accumulate → chronic inflammation/fibrosis develop → firm non-pitting lymphoedema appears.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Thoracic duct</strong></th>\n  <th><strong>Right lymphatic duct</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Drains</td>\n  <td>Both lower limbs, abdomen and left upper body.</td>\n  <td>Right upper limb, right chest, right head/neck.</td>\n</tr>\n<tr>\n  <td>Venous outlet</td>\n  <td>Left jugulo-subclavian junction.</td>\n  <td>Right jugulo-subclavian junction.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Long-chain dietary fats</strong></th>\n  <th><strong>Short-/medium-chain fats</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Absorption route</td>\n  <td>Chylomicrons through intestinal lacteals and lymph.</td>\n  <td>Primarily portal venous blood.</td>\n</tr>\n<tr>\n  <td>Lymphatic dependence</td>\n  <td>High.</td>\n  <td>Much lower.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Lymph nodes</strong> provide the main pumping force for lymph → Truth: Vessel contractions and external mechanical pumps move lymph; nodes filter.</li>\n<li>Trap: <strong>Thoracic duct</strong> drains only the left chest → Truth: It drains most of the body including both lower limbs and the abdomen.</li>\n<li>Trap: <strong>Lymphatics</strong> only carry extra water → Truth: They return escaped plasma protein and transport dietary long-chain fat.</li>\n<li>Trap: <strong>Lymphatic capillary flaps</strong> require an active muscular valve → Truth: Tissue-to-lymph pressure differences move overlapping endothelial flaps.</li>\n<li>Trap: <strong>Lymphoedema</strong> is always soft and pitting indefinitely → Truth: Protein accumulation causes chronic inflammation and fibrosis, producing firm non-pitting swelling.</li>\n</ul>\n"}]};
